diff --git a/core/forks/orchestrator.js b/core/forks/orchestrator.js
index a7f71e2..7b04af9 100644
--- a/core/forks/orchestrator.js
+++ b/core/forks/orchestrator.js
@@ -161,6 +161,13 @@ function resumeFork(options) {
   const objective = options.objective || readPrivate(projectRoot, fork.fork_id, 'objective.txt').trim();
   const signingKey = options.signingKey || readPrivate(projectRoot, fork.fork_id, 'signing-key.pem');
   const workflow = options.workflow || JSON.parse(readPrivate(projectRoot, fork.fork_id, 'workflow.json'));
+  // Resume is the only path that can supply a workflow, so both shared digests are
+  // re-checked before any branch runs: a substituted or drifted verifier would
+  // otherwise produce evidence the fork's contract never authorized.
+  if (operations.sha256Digest(workflow) !== fork.shared.workflow_digest
+    || operations.sha256Digest(workflow.verifier) !== fork.shared.verifier_digest) {
+    throw Object.assign(new Error('Workflow does not match fork contract'), { code: 'FORK_WORKFLOW_MISMATCH' });
+  }
   const profiles = loadExecutorProfiles(projectRoot, fork);

   for (const branchSnapshot of [...fork.branches]) {
