--- a/scripts/test-operation-fork.js
+++ b/scripts/test-operation-fork.js
@@ -119,6 +119,24 @@ assert.equal(resumed.fork.branches.find((branch) => branch.runtime === 'claude')
 assert.equal(resumed.fork.branches.find((branch) => branch.runtime === 'claude').failure_code, 'RUNTIME_EFFECT_AMBIGUOUS');
 assert.deepEqual(calls, ['codex'], 'ambiguous Claude effect must not run again');

+const forgedWorkflow = { ...workflow, verifier: { command: process.execPath, args: ['-e', 'process.exit(1)'] } };
+const beforeForged = forks.loadFork(project, 'fork-recovery');
+assert.throws(() => forks.resumeFork({ projectRoot: project, forkId: 'fork-recovery', workflow: forgedWorkflow,
+  worktreeRoot: worktrees, worktreeProvider: provider,
+  runBranch: () => assert.fail('contract-mismatched workflow must not run a branch') }),
+(error) => error.code === 'FORK_WORKFLOW_MISMATCH', 'resume must reject a workflow outside the shared contract');
+assert.throws(() => forks.resumeFork({ projectRoot: project, forkId: 'fork-recovery',
+  workflow: { ...workflow, id: 'workflow-drifted' },
+  worktreeRoot: worktrees, worktreeProvider: provider,
+  runBranch: () => assert.fail('drifted workflow must not run a branch') }),
+(error) => error.code === 'FORK_WORKFLOW_MISMATCH', 'resume must reject a drifted workflow with the contract verifier');
+const afterForged = forks.loadFork(project, 'fork-recovery');
+assert.equal(afterForged.revision, beforeForged.revision, 'rejected resume must not write state');
+assert.deepEqual(afterForged.branches.map((branch) => branch.status), beforeForged.branches.map((branch) => branch.status));
+const reresumed = forks.resumeFork({ projectRoot: project, forkId: 'fork-recovery',
+  worktreeRoot: worktrees, worktreeProvider: provider, runBranch: fakeRun });
+assert.equal(reresumed.fork.revision, beforeForged.revision, 'durable contract workflow still resumes');
